STORY = [('muranishi', '村西とおるでございます。', 'I am Toru Muranishi.', [(556, '村西とおるでございます')], ''), ('keieisha', 'あんた一体目的は何なんだ？', "Just what on earth is it that you're after?", [(558, 'あんた 一体 目的は何なんだ')], ''), ('keieisha', '喜べ！彼のおかげで五社協定が成立したぞ。', 'Rejoice! Thanks to him, our five-company alliance has gone through!', [(567, '喜べ'), (568, '彼のおかげで ５社協定が成立したぞ')], 'spelled numeral in kanji'), ('keieisha', 'ご令嬢が村西君をいたく気に入ってな。', 'The heiress took an immense liking to Muranishi here.', [(570, 'ご令嬢が 村西君を いたく気に入ってな')], ''), ('keieisha', '村西君にはお礼に衛星の回線をやることにした。契約許可出しといてくれ。', 'To thank Muranishi, I decided to give him a satellite channel. Issue him contract approval.', [(576, '村西君には お礼に 衛星の回線をやることにした'), (577, '契約許可 出しといてくれ')], ''), ('shacho', 'ちょっと待ってください！どうしてこんな男に？', 'Wait a second, sir! Why give one to a man like him?', [(578, 'ちょっと待ってください'), (579, 'どうして こんな男に')], ''), ('keieisha', 'お前にできなかったことをやってのけたからだろ。この男はお前よりずっと面白い。', "Because he pulled off what you couldn't! This man is far more interesting than you.", [(581, 'お前にできなかったことを やってのけたからだろ'), (583, 'この男は お前よりずっと面白い')], ''), ('shacho', 'この男は前科者ですよ！グループの事業に傷がつきますよ。', "This man is an ex-convict! He will stain our group's businesses!", [(587, 'この男は前科者ですよ'), (588, 'グループの事業に傷がつきますよ')], ''), ('keieisha', '我々とてきれい事だけでここまで来たわけじゃないぞ。前科なんてのは勲章みたいなもんだ！', "We didn't climb this far on saintly deeds alone either! A criminal record is like a medal of honor!", [(591, '我々とて きれい事だけで ここまで来たわけじゃないぞ'), (592, '前科なんてのは 勲章みたいなもんだ')], ''), ('muranishi', '覚えていただけましたか？わたくしの名前。前科者の村西とおるでございます。', 'Have you remembered my name yet? I am the ex-convict, Toru Muranishi.', [(595, '覚えていただけましたか わたくしの名前'), (597, '前科者の村西とおるでございます')], ''), ('muranishi', 'このご恩は必ず報います。', 'I swear I will repay this kindness without fail.', [(604, 'このご恩は必ず報います')], ''), ('keieisha', 'ここからは自由競争だ。最初の作品が命運を分けるぞ、しっかりやることだ。', 'From here on it is open competition. Your first work will decide your fate—make it count.', [(605, 'ここからは自由競争だ'), (607, '最初の作品が命運を分けるぞ しっかりやることだ')], '')]
